    protected void createGenModelAnnotations() {
        String source = "http://www.eclipse.org/emf/2002/GenModel";
        this.addAnnotation((ENamedElement)this.endToEndDescriptionEClass, source, new String[]{"documentation", "This meta-class contains information about end-to-end protection. The set of applicable attributes depends on the actual value of the category attribute of EndToEndProtection."});
        this.addAnnotation((ENamedElement)this.getEndToEndDescription_Category(), source, new String[]{"documentation", "The category represents the identification of the concrete E2E profile. The applicable values are specified in a semantic constraint and determine the applicable attributes of EndToEndDescription.\r\n"});
        this.addAnnotation((ENamedElement)this.getEndToEndDescription_DataIds(), source, new String[]{"documentation", "This represents a unique numerical identifier. \r\nNote: ID is used for protection against masquerading. The details concerning the maximum number of values (this information is specific for each E2E profile) applicable for this attribute are controlled by a semantic constraint that depends on the category of the EndToEndProtection.\r\n"});
        this.addAnnotation((ENamedElement)this.getEndToEndDescription_DataIdMode(), source, new String[]{"documentation", "There are three inclusion modes how the implicit two-byte Data ID is included in the one-byte CRC:\r\n\r\n* dataIDMode = 0: Two bytes are included in the CRC (double ID configuration) This is used in variant 1A.\r\n* dataIDMode = 1: One of the two bytes byte is included, alternating high and low byte, depending on parity of the counter (alternating ID configuration). For even counter low byte is included; For odd counters the high byte is included. This is used in variant 1B.\r\n* dataIDMode = 2: Only low byte is included, high byte is never used. This is applicable if the IDs in a particular system are 8 bits.\r\n"});
        this.addAnnotation((ENamedElement)this.getEndToEndDescription_DataLength(), source, new String[]{"documentation", "This attribute represents the length of the Array representation of the Signal Group/DataElementPrototype including CRC and Counter in bits.\r\n"});
        this.addAnnotation((ENamedElement)this.getEndToEndDescription_MaxDeltaCounterInit(), source, new String[]{"documentation", "Initial maximum allowed gap between two counter values of two consecutively received valid Data, i.e. how many subsequent lost data is accepted. For example, if the receiver gets Data with counter 1 and MaxDeltaCounterInit is 1, then at the next reception the receiver can accept Counters with values 2 and 3, but not 4.\r\n\r\nNote that if the receiver does not receive new Data at a consecutive read, then the receiver increments the tolerance by 1.\r\n"});
        this.addAnnotation((ENamedElement)this.getEndToEndDescription_CrcOffset(), source, new String[]{"documentation", "Bit offset of CRC from the beginning of the Array representation of the Signal Group/DataElementPrototype (MSB order, bit numbering: bit 0 is the least important). The offset shall be a multiplicity of 8 and it should be 0 whenever possible. For example, offset 8 means that the CRC will take the byte 1, i.e. bits 8..15. If crcOffset is not present the value is defined by the selected profile."});
        this.addAnnotation((ENamedElement)this.getEndToEndDescription_CounterOffset(), source, new String[]{"documentation", "Bit offset of Counter from the beginning of the Array representation of the Signal Group/DataElementPrototype (MSB order, bit numbering: bit 0 is the least important). The offset shall be a multiplicity of 4 and it should be 8 whenever possible. For example, offset 8 means that the counter will take the low nibble of the byte 1, i.e. bits 8 .. 11. If counterOffset is not present the value is defined by the selected profile.\r\n"});
        this.addAnnotation((ENamedElement)this.endToEndProtectionEClass, source, new String[]{"documentation", "This meta-class represents the ability to describe a particular end to end protection.\r\n"});
        this.addAnnotation((ENamedElement)this.getEndToEndProtection_EndToEndProfile(), source, new String[]{"documentation", "This represents the particular EndToEndDescription."});
        this.addAnnotation((ENamedElement)this.getEndToEndProtection_EndToEndProtectionDataElementPrototypes(), source, new String[]{"documentation", "Defines to which DataElementPrototypes in the roles of one sender and one or more receivers this EndToEndprotection shall apply.\r\n\r\nIn case several senders are defined to transport the data there may exist several EndToEndProtectionDataElementPrototype elements."});
        this.addAnnotation((ENamedElement)this.getEndToEndProtection_EndToEndProtectionISignalIPdus(), source, new String[]{"documentation", "Defines to which ISignalIPdu - ISignal pair this EndToEndProtection shall apply.\r\n\r\nIn case several ISignals are used to transport the data (e.g. fan-out in the RTE) there may exist several EndToEndProtectionISignalIPdu definitions."});
        this.addAnnotation((ENamedElement)this.endToEndProtectionDataElementPrototypeEClass, source, new String[]{"documentation", "It is possible to protect the data exchanged between software components. For this purpose, for each communication to be protected,  the user defines a separate EndToEndProtection (specifying a set of protection settings) and refers to a dataElement in the role of sender and to one or many dataElements in the role of receiver. For details, see End to End Library.\r\n"});
        this.addAnnotation((ENamedElement)this.getEndToEndProtectionDataElementPrototype_Receivers(), source, new String[]{"documentation", "This represnets the receiver. Note that 1:n communication is supported for this use case.\r\n\r\nCan be optional if an ecu extract is provided and no receiver is part of the extract.\r\nThis represnets the receiver. Note that 1:n communication is supported for this use case."});
        this.addAnnotation((ENamedElement)this.getEndToEndProtectionDataElementPrototype_Sender(), source, new String[]{"documentation", "This represents the sender.\r\n\r\nCan be optional if an ecu extract is provided and the sender is part of the extract."});
        this.addAnnotation((ENamedElement)this.endToEndProtectionSetEClass, source, new String[]{"documentation", "This represents a container for collection EndToEndProtectionInformation.\r\n"});
        this.addAnnotation((ENamedElement)this.getEndToEndProtectionSet_EndToEndProtections(), source, new String[]{"documentation", "This is one particular EndToEndProtection."});
    }

